620	// A storage write failure reports a clear error and poisons the queue; after
621	// reopening, the torn unacknowledged tail is dropped and consistency holds.
622	func TestStorageFailureRecovery(t *testing.T) {
623		dir := t.TempDir()
624		q, err := Open(dir)
625		if err != nil {
626			t.Fatal(err)
627		}
628		q.RegisterSource("a")
629		q.store.injectErr = errors.New("disk on fire")
630		if _, err := q.Submit(env("m", "a", "b", 1, 10, 0)); !errors.Is(err, ErrStorage) {
631			t.Fatalf("want ErrStorage, got %v", err)
632		}
633		// Further writes must fail loudly instead of corrupting the log.
634		if err := q.RegisterSource("c"); !errors.Is(err, ErrStorage) {
635			t.Fatalf("broken queue must refuse writes, got %v", err)
636		}
637		q.Close()
638	
639		q2, err := Open(dir)
640		if err != nil {
641			t.Fatalf("reopen after storage failure: %v", err)
642		}
643		defer q2.Close()
644		if _, ok := q2.Query("m"); ok {
645			t.Fatalf("unacknowledged submit must not exist after recovery")
646		}
647		if !q2.sources["a"] {
648			t.Fatalf("acknowledged source registration lost")
649		}
650	}
651	
652	// Concurrent goroutines sharing one Queue must never double-consume a nonce.
653	func TestConcurrentNoDoubleConsume(t *testing.T) {
654		q, _ := openTempQueue(t)
655		defer q.Close()
656		q.RegisterSource("a")
657		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
658	
659		const n = 40
660		var wg sync.WaitGroup
661		for i := 0; i < n; i++ {
662			wg.Add(1)
663			go func(i int) {
664				defer wg.Done()
665				_, _ = q.Submit(env(fmt.Sprintf("m%d", i), "a", "b", uint64(i%3), 10, 0))
666			}(i)
667		}
668		wg.Wait()
669		rep, err := q.Advance(1000)
670		if err != nil {
671			t.Fatal(err)
672		}
673		delivered := map[uint64]int{}
674		for _, res := range rep.Results {
675			if res.Status == StatusSuccess {
676				delivered[q.records[res.ID].Msg.Message.Nonce]++
677			}
678		}
679		if len(delivered) != 3 {
680			t.Fatalf("want exactly 3 consumed nonces, got %d", len(delivered))
681		}
682		for nonce, count := range delivered {
683			if count != 1 {
684				t.Fatalf("nonce %d delivered %d times", nonce, count)
685			}
686		}
687		replays := 0
688		for _, res := range rep.Results {
689			if res.Status == StatusReplay {
690				replays++
691			}
692		}
693		if replays != n-3 {
694			t.Fatalf("want %d replays, got %d", n-3, replays)
695		}
696		if len(q.consumed) != 3 {
697			t.Fatalf("consumed set: %v", q.consumed)
698		}
699	}
