753	// A later trusted header must not resurrect an expired message.
754	func TestHeaderDoesNotReactivateExpired(t *testing.T) {
755		q, _ := openTempQueue(t)
756		defer q.Close()
757		q.RegisterSource("a")
758		q.Submit(env("m", "a", "b", 1, 1000, 3000))
