// crossingSubmit returns a pending-destined envelope whose single submit frame
// takes the active log from at/below the threshold to strictly above it. The
// payload is grown with single-byte JSON characters, so appending exactly this
// envelope at q.nextSeq is the first append that crosses; one payload byte
// less would stay at or under the threshold.
func crossingSubmit(q *Queue, id, from, to string, nonce uint64, proofAt, expiresAt int64) Envelope {
	e := Envelope{Message: Message{ID: id, From: from, To: to, Nonce: nonce, ProofAt: proofAt}, ExpiresAt: expiresAt}
	base := submitFrameSize(e, q.nextSeq)
	need := compactThreshold-int(q.store.size)-base + 1
	if need < 1 {
		need = 1
	}
	e.Message.Payload = strings.Repeat("A", need)
	if grown := int(q.store.size) + submitFrameSize(e, q.nextSeq); grown <= compactThreshold {
		e.Message.Payload += strings.Repeat("A", compactThreshold-grown+1)
	}
	if int(q.store.size)+submitFrameSize(e, q.nextSeq) <= compactThreshold {
		panic("crossingSubmit failed to cross the compaction threshold")
	}
	return e
}

input.new_string:
// crossingSubmit returns a pending-destined envelope whose single submit frame
// takes the active log from at/below the threshold to exactly threshold+1
// bytes, i.e. it is the first append that crosses (needsCompaction is a strict
// >). Payload bytes are single-byte JSON characters; the size is measured
// against the real framed record, so the JSON field overhead is accounted for
// and subtracting one payload byte would stay at or under the threshold.
func crossingSubmit(q *Queue, id, from, to string, nonce uint64, proofAt, expiresAt int64) Envelope {
	e := Envelope{Message: Message{ID: id, From: from, To: to, Nonce: nonce, ProofAt: proofAt}, ExpiresAt: expiresAt}
	need := compactThreshold-int(q.store.size)-submitFrameSize(e, q.nextSeq) + 1
	if need < 1 {
		need = 1
	}
	// Frame size is linear in payload length once the field is present; the
	// first bytes also pay the JSON field wrapper, so converge in a few steps.
	for range 5 {
		e.Message.Payload = strings.Repeat("A", need)
		total := int(q.store.size) + submitFrameSize(e, q.nextSeq)
		if total == compactThreshold+1 {
			return e
		}
		need += compactThreshold + 1 - total
		if need < 1 {
			need = 1
		}
	}
	panic("crossingSubmit failed to land exactly one byte past the threshold")
}

