191		n, _ := crossThresholdWithFatSubmits(t, state)
192	
193		// Deliver all fillers first; the advance itself also compacts, so by the
194		// time the pair arrives every append rewrites the snapshot.
195		rep := advanceCLI(t, state, 1_700_000_000_000)
196		if len(rep.Results) != n {
197			t.Fatalf("setup: want %d filler successes, got %d", n, len(rep.Results))
198		}
199	
200		first := cliSubmitSpec{
201			id: "first", from: "chain-a", to: "chain-b", nonce: 7,
202			payload: "first-body", proofAt: 100, expiresAt: 9_000_000_000_000,
203		}
204		second := cliSubmitSpec{
205			id: "second", from: "chain-a", to: "chain-b", nonce: 7,
206			payload: "second-body", proofAt: 100, expiresAt: 9_000_000_000_000,
207		}
208	
209		ino, _ := logStat(t, state)
210		echo1, _ := mustSubmit(t, state, first)
211		if echo1.Status != "pending" || echo1.Attempts != 0 || echo1.NextRetry != 0 {
212			t.Fatalf("first must be pending and unprocessed: %+v", echo1)
213		}
214		if ino1, _ := logStat(t, state); ino1 == ino {
215			t.Fatal("submitting first must have compacted the over-threshold log")
216		} else {
217			ino = ino1
218		}
219		echo2, _ := mustSubmit(t, state, second)
220		if echo2.Status != "pending" || echo2.Attempts != 0 || echo2.NextRetry != 0 {
221			t.Fatalf("second must be pending and unprocessed: %+v", echo2)
222		}
223		if ino2, _ := logStat(t, state); ino2 == ino {
224			t.Fatal("submitting second must have compacted the over-threshold log")
225		}
226	
227		// Both experience compaction before first processing; now advance. The
228		// fillers are terminal, so the report carries exactly the pair, in order.
229		rep = advanceCLI(t, state, 1_700_000_001_000)
230		if len(rep.Results) != 2 {
231			t.Fatalf("want exactly the pair processed, got %+v", rep.Results)
232		}
233		if r := rep.Results[0]; r.ID != "first" || r.Status != "success" ||
234			r.Reason != "delivered; proof verified by trusted header at height 100" {
235			t.Fatalf("first-submitted message must win: %+v", r)
236		}
237		if r := rep.Results[1]; r.ID != "second" || r.Status != "replay" ||
238			r.Reason != "nonce combination already consumed by message first" {
239			t.Fatalf("second-submitted message must be replay pointing at first: %+v", r)
240		}
241	
242		gotFirst := queryFull(t, state, "first")
243		if gotFirst.Status != "success" || gotFirst.Attempts != 1 || gotFirst.NextRetry != 0 ||
244			gotFirst.Payload != "first-body" {
245			t.Fatalf("first stored state wrong: %+v", gotFirst)
246		}
247		gotSecond := queryFull(t, state, "second")
248		if gotSecond.Status != "replay" || gotSecond.Attempts != 1 || gotSecond.NextRetry != 0 ||
249			gotSecond.Payload != "second-body" ||
250			gotSecond.Reason != "nonce combination already consumed by message first" {
251			t.Fatalf("second stored state wrong: %+v", gotSecond)
252		}
253	
254		// Full listing order and uniqueness, read from a freshly reopened compacted
255		// directory: fillers, first, second, each exactly once.
256		all := queryAll(t, state)
257		if len(all) != n+2 {
258			t.Fatalf("want %d unique records, got %d", n+2, len(all))
259		}
260		if all[0].ID != "fat-01" || all[n-1].ID != fmt.Sprintf("fat-%02d", n) ||
261			all[n].ID != "first" || all[n+1].ID != "second" {
262			t.Fatalf("listing order wrong around the pair: %v", append(recordIDs(all)[n-1:n], recordIDs(all)[n:]...))
263		}
264	
265		// A later advance never reprocesses the terminal pair.
266		again := advanceCLI(t, state, 1_700_000_100_000)
267		if len(again.Results) != 0 {
268			t.Fatalf("terminal records must not reappear: %+v", again.Results)
269		}
270		if got := queryFull(t, state, "second"); got.Attempts != 1 || got.Status != "replay" {
271			t.Fatalf("second must keep one attempt and replay status: %+v", got)
272		}
273	}
274	
275	// Submit-time identity boundaries for a message still pending after automatic
276	// compaction: resubmitting the same id with identical content returns the
277	// existing record and adds nothing, while different content exits 13 as a
278	// content conflict with the original record fully intact and the submission
279	// order unchanged. A later advance processes everything in the original order
280	// using the original payload, identical to the non-compacted rules.
281	func TestCLIAutoCompactionSubmitConflictBoundaries(t *testing.T) {
282		state := t.TempDir()
283		registerSource(t, state, "chain-a")
284		if r := storeHeader(t, state, "chain-a", 100, "0x100", true); r.code != 0 {
285			t.Fatalf("store header: %v", r)
286		}
287		n, _ := crossThresholdWithFatSubmits(t, state)
288	
289		dup := cliSubmitSpec{
290			id: "dup", from: "chain-a", to: "chain-b", nonce: 70,
291			payload: "orig-body", proofAt: 100, expiresAt: 9_000_000_000_000,
292		}
293		ino, _ := logStat(t, state)
294		firstEcho, rawFirst := mustSubmit(t, state, dup)
295		if ino1, _ := logStat(t, state); ino1 == ino {
296			t.Fatal("submitting dup must have compacted the over-threshold log")
297		} else {
298			ino = ino1
299		}
300		beforeIDs := recordIDs(queryAll(t, state))
301		if len(beforeIDs) != n+1 || beforeIDs[n] != "dup" {
302			t.Fatalf("setup listing wrong: %d entries, tail %v", len(beforeIDs), beforeIDs)
303		}
304	
305		// Identical resubmit: same record, no append (inode unchanged), no extra
306		// entry, same order.
307		echo, rawEcho := mustSubmit(t, state, dup)
308		if rawEcho != rawFirst || echo != firstEcho {
309			t.Fatalf("identical resubmit must echo the existing record:\n%s\n%s", rawFirst, rawEcho)
310		}
311		if inoSame, _ := logStat(t, state); inoSame != ino {
312			t.Fatal("an idempotent resubmit must append nothing and not recompact")
313		}
314		if ids := recordIDs(queryAll(t, state)); len(ids) != n+1 || ids[n] != "dup" {
315			t.Fatalf("identical resubmit must add no record: %v", ids)
316		}
