319		changed := dup
320		changed.payload = "changed-body"
321		assertContentConflict(t, submitRaw(t, state, changed), "dup")
322		if inoSame, _ := logStat(t, state); inoSame != ino {
323			t.Fatal("a rejected resubmit must append nothing and not recompact")
324		}
325		got := queryFull(t, state, "dup")
326		if got.Payload != "orig-body" || got.Nonce != 70 || got.ProofAt != 100 ||
327			got.ExpiresAt != 9_000_000_000_000 || got.Status != "pending" ||
328			got.Attempts != 0 || got.NextRetry != 0 {
329			t.Fatalf("original dup record must stay intact after conflict: %+v", got)
330		}
331		if ids := recordIDs(queryAll(t, state)); len(ids) != n+1 || ids[n] != "dup" {
332			t.Fatalf("rejected resubmit must add no record and keep order: %v", ids)
333		}
334		// The original content still resubmits idempotently.
335		if echo2, _ := mustSubmit(t, state, dup); echo2 != firstEcho {
336			t.Fatalf("identical resubmit after rejected resubmit must still return the original: %+v", echo2)
337		}
338	
339		// Processing order is unaffected: every filler then dup succeeds, once, in
340		// first-submission order, using the original payload.
341		rep := advanceCLI(t, state, 1_700_000_000_000)
342		if len(rep.Results) != n+1 {
343			t.Fatalf("want %d deliveries, got %d", n+1, len(rep.Results))
344		}
