350			got.Reason != "delivered; proof verified by trusted header at height 100" {
351			t.Fatalf("dup must deliver exactly once with its original body: %+v", got)
352		}
353		if ids := recordIDs(queryAll(t, state)); len(ids) != n+1 || ids[n] != "dup" {
